INSERT INTO fund_report_vector (fund_code, manager_name, report_quarter, section_title, content) VALUES ('005827', '张坤', '2024Q2', '管理人对报告期内投资策略与运作分析', '我们依然长期看好商业模式优秀、具备极强自由现金流产生能力与宽阔护城河的商业龙头。在经济周期波动中，优秀企业的市占率与竞争壁垒往往进一步提升。组合在二季度维持了消费与科技龙头的核心配置，重视企业的分红意愿与股东回报率，不轻易做风格轮动与仓位博弈，坚信时间是优秀企业的朋友。');
INSERT INTO fund_report_vector (fund_code, manager_name, report_quarter, section_title, content) VALUES ('161005', '朱少醒', '2024Q2', '管理人对报告期内投资策略与运作分析', '本基金在二季度依然保持高仓位运作。我们坚持自下而上精选具有良好企业基因、治理结构优良、并且估值处于合理或低估区间的优秀成长企业。在行业配置上相对淡化宏观择时，侧重于组合的均衡性与行业分散度，积极寻找具备长期翻倍潜力但目前被市场情绪错杀的隐形制造业与科技制造业冠军。');
